export interface ProductCategory {
  slug: string
  label: string
  /** Describes the photo, for screen readers. */
  alt: string
  /** CSS object-position: keeps the product centred in the 4:3 crop. */
  focus?: string
}

/**
 * Optimized thumbnails generated by `npm run assets` (scripts/generate-assets.mjs)
 * from the originals in public/asset/home-4th-section-products-*.
 */
export const categoryImage = (slug: string, width: 480 | 960) =>
  `/asset/products/${slug}-${width}.webp`

